def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()
    write_time = {}
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries for accounting purposes
            expired_keys = [k for k in cache if write_time[k] + ttl <= t]
            for k in expired_keys:
                del cache[k]
                del write_time[k]

            if key in cache:
                # Key exists: update it and move to end (most recently used)
                cache.move_to_end(key)
                cache[key] = value
                write_time[key] = t
            else:
                # Key doesn't exist
                if len(cache) >= capacity:
                    # Evict least recently used
                    lru_key, _ = cache.popitem(last=False)
                    del write_time[lru_key]

                cache[key] = value
                write_time[key] = t

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and hasn't expired
            if key in cache and write_time[key] + ttl > t:
                # Move to end (most recently used)
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)

    return results

